import {h,icon,button as btn} from './ui.mjs';
import {formatCopyTime} from './recovery.mjs';
export function cloudMessage(status){
 if(status.phase==='local')return 'HTML-версия хранит прогресс только в этом браузере. Для переноса используй выгрузку и загрузку JSON.';
 const messages={connecting:'Проверяем сохранённый прогресс…',saved:'Прогресс сохранён и синхронизирован.',pending:'Есть изменения на устройстве. Ожидаем сохранения.',saving:'Сохраняем прогресс…',offline:'Нет связи. Копия на устройстве сохранена; синхронизация возобновится при подключении.',error:status.message==='signin'?'Для синхронизации открой опубликованное приложение и войди в свой аккаунт.':status.message==='storage'?'Браузеру не хватает места для резервной копии. Выгрузи прогресс перед заменой данных.':'Синхронизация временно недоступна. Копия на устройстве сохраняется.',conflict:'Есть две версии прогресса. Выбери, какую использовать.',deferred:'Есть обновление с другого устройства. Оно загрузится после завершения занятия или закрытия формы.'};
 return messages[status.phase]||messages.pending;
}
export function cloudCopyButtons(copies=[]){
 if(copies.length<2)return '';
 return `<div class="button-row cloud-copies" role="group" aria-label="Более ранние копии">${copies.slice(1).map(copy=>btn(`Копия от ${h(formatCopyTime(copy.savedAt)||'—')} · ${copy.local.xp} XP`,'cloud-recovery','secondary',`data-id="${copy.id}"`)).join('')}</div><p class="field-note">Хранятся три последние копии устройства; более ранние заменяются новыми.</p>`;
}
export function cloudSettings(status,conflict,copies=[]){if(status.phase==='local')return `<section class="panel continuity-panel"><div><span class="continuity-icon">${icon('download')}</span><div><h2>Прогресс в HTML-версии</h2><p>${h(cloudMessage(status))}</p></div></div><p class="field-note">Сохрани JSON перед обновлением или перемещением HTML-файла. Работа хранилища локальных файлов зависит от браузера; очистка его данных удаляет локальные результаты.</p></section>`;return `<section class="panel continuity-panel"><div><span class="continuity-icon">${icon('repeat')}</span><div><h2>Продолжай на другом устройстве</h2><p data-cloud-status role="status">${h(cloudMessage(status))}</p></div></div><p class="field-note">Используй тот же аккаунт и адрес приложения. Незавершённый урок остаётся на своём устройстве; завершённые результаты, слова и настройки переносятся. Перед заменой сохраняется резервная копия.</p><div class="button-row">${btn('Проверить синхронизацию','cloud-retry','secondary')}${conflict?btn('Выбрать версию','cloud-conflict','secondary'):''}${btn('Копия до замены','cloud-recovery','secondary','data-id="0"')}</div>${cloudCopyButtons(copies)}</section>`;}
